"""SQLite JSON documents: types, paths, relational expansion and updates."""
from _draft_helpers import topic

S = """
CREATE TABLE document(id INTEGER PRIMARY KEY,body TEXT CHECK(json_valid(body)));
INSERT INTO document VALUES
 (1,'{"name":"Ann","active":true,"note":null,"tags":["red","blue"],"items":[{"sku":"A","qty":2},{"sku":"B","qty":1}]}'),
 (2,'{"name":"Bob","active":false,"tags":[],"items":[{"sku":"A","qty":3}]}'),
 (3,'{"name":"Cara","active":true,"note":"x","tags":["red"],"items":[]}');
"""
def T(n,slug,title,concepts,explain,q,out,p,a,b):
    return topic(n,slug,title,"json",concepts,explain,S,q,out,p,a,b)

LESSONS = [
 T(157,"json-null-vs-absent","区分 JSON null 与属性不存在",["JSON_TYPE","JSON_EXTRACT","缺失属性"],
   "JSON_EXTRACT 对 JSON null 和不存在的路径都返回 SQL NULL；JSON_TYPE 却分别返回文本 null 和 SQL NULL。三行的 note 状态依次为 null、missing、text，导入补丁时必须据此区分明确清空和未提供属性。",
   "SELECT id,coalesce(json_type(body,'$.note'),'missing') FROM document ORDER BY id;","1|null\n2|missing\n3|text",
   ["IS NULL 无法独自区分 JSON null 与缺少属性。","路径语法不是普通 SQL 列名。"],
   ("仅返回明确把 note 设为 JSON null 的文档。","JSON_TYPE 返回字符串 null。","SELECT id FROM document WHERE json_type(body,'$.note')='null' ORDER BY id;","1"),
   ("仅返回没有 note 属性的文档。","检查 JSON_TYPE IS NULL。","SELECT id FROM document WHERE json_type(body,'$.note') IS NULL ORDER BY id;","2")),
 T(158,"json-boolean-type","JSON 布尔值与 SQL 整数映射",["JSON 布尔","类型映射","条件查询"],
   "JSON true 和 false 被 JSON_EXTRACT 映射为 SQL 整数 1 和 0，但 JSON_TYPE 仍标明 true/false。Ann 与 Cara 为真，Bob 为假。数字 1 与布尔 true 在抽取后可能相等，要求严格布尔时需同时检查类型。",
   "SELECT id,json_extract(body,'$.active'),json_type(body,'$.active') FROM document ORDER BY id;","1|1|true\n2|0|false\n3|1|true",
   ["JSON 布尔抽取结果不是文本 true。","宽松数值比较会丢失原始 JSON 类型差异。"],
   ("找出严格 JSON true 的姓名。","使用 JSON_TYPE='true'。","SELECT json_extract(body,'$.name') FROM document WHERE json_type(body,'$.active')='true' ORDER BY id;","Ann\nCara"),
   ("统计严格 JSON false 的文档数。","按原始类型过滤。","SELECT count(*) FROM document WHERE json_type(body,'$.active')='false';","1")),
 T(159,"json-expand-array","数组展开时保留元素下标",["JSON_EACH","数组","元素顺序"],
   "JSON_EACH 把 tags 的直接元素变为行，key 是从零开始的数组下标。Ann 得到 red、blue，Cara 得到 red，Bob 的空数组没有元素行。按文档 id 和数值 key 排序，才能稳定重现数组顺序。",
   "SELECT d.id,j.key,j.value FROM document d,json_each(d.body,'$.tags') j ORDER BY d.id,j.key;","1|0|red\n1|1|blue\n3|0|red",
   ["内展开会隐藏空数组文档。","对象的 key 是文本，不应当作数组下标。"],
   ("找到拥有 red 标签的文档 id。","使用 EXISTS，避免一个文档重复出现。","SELECT d.id FROM document d WHERE EXISTS(SELECT 1 FROM json_each(d.body,'$.tags') j WHERE j.value='red') ORDER BY d.id;","1\n3"),
   ("列出每个标签覆盖的不同文档数。","按 value 分组。","SELECT j.value,count(DISTINCT d.id) FROM document d,json_each(d.body,'$.tags') j GROUP BY j.value ORDER BY j.value;","blue|1\nred|2")),
 T(160,"json-left-expand","左展开数组保留空文档",["LEFT JOIN","JSON_EACH","空数组"],
   "LEFT JOIN JSON_EACH 让空 tags 的 Bob 仍保留一行；COUNT(j.key) 只统计真实元素，依次为 2、0、1。若改为 COUNT(*)，Bob 的占位连接行会被误算为一个标签。",
   "SELECT d.id,count(j.key) FROM document d LEFT JOIN json_each(d.body,'$.tags') j ON 1 GROUP BY d.id ORDER BY d.id;","1|2\n2|0\n3|1",
   ["COUNT(*) 会计算左连接保留的空行。","过滤展开结果时注意 WHERE 可能把左连接退化为内连接。"],
   ("返回完全没有标签的文档姓名。","JSON_ARRAY_LENGTH=0。","SELECT json_extract(body,'$.name') FROM document WHERE json_array_length(body,'$.tags')=0 ORDER BY id;","Bob"),
   ("计算所有标签元素总数。","对每个数组长度求和。","SELECT sum(json_array_length(body,'$.tags')) FROM document;","3")),
 T(161,"json-nested-line-items","嵌套 JSON 行项目转关系汇总",["嵌套对象","JSON_EXTRACT","行项目"],
   "先展开 items，再从每个对象取 sku 和 qty，按 sku 求和。A 来自 Ann 的 2 与 Bob 的 3，总量 5；B 只有 1。不要直接对完整 JSON 文本分组，否则同商品的不同数量会形成不同组。",
   "SELECT json_extract(j.value,'$.sku') sku,sum(json_extract(j.value,'$.qty')) FROM document d,json_each(d.body,'$.items') j GROUP BY sku ORDER BY sku;","A|5\nB|1",
   ["展开后每行是行项目，粒度已经不同于文档。","数量类型应在导入时校验，避免文本参与求和。"],
   ("返回各文档的商品件数，空列表补零。","使用相关 SUM 子查询。","SELECT d.id,coalesce((SELECT sum(json_extract(j.value,'$.qty')) FROM json_each(d.body,'$.items') j),0) FROM document d ORDER BY d.id;","1|3\n2|3\n3|0"),
   ("找出含两种及以上行项目的文档。","JSON_ARRAY_LENGTH 检查结构数量。","SELECT id FROM document WHERE json_array_length(body,'$.items')>=2 ORDER BY id;","1")),
 T(162,"json-recursive-leaves","JSON_TREE 递归检查所有叶子",["JSON_TREE","atom","递归 JSON"],
   "JSON_TREE 遍历整个子树，atom 保存标量叶子，数组和对象容器的 atom 为空。对 Ann 的 items 仅保留非空 atom，得到四个路径和值。fullkey 提供精确路径，适合本地配置审计，但路径不是稳定业务标识。",
   "SELECT j.fullkey,j.atom FROM document d,json_tree(d.body,'$.items') j WHERE d.id=1 AND j.atom IS NOT NULL ORDER BY j.fullkey;","$.items[0].qty|2\n$.items[0].sku|A\n$.items[1].qty|1\n$.items[1].sku|B",
   ["atom IS NOT NULL 同时排除了 JSON null 叶子。","对象键顺序不应作为业务排序保证。"],
   ("统计所有 items 子树中的整数叶子数量。","按 JSON_TREE.type 过滤。","SELECT count(*) FROM document d,json_tree(d.body,'$.items') j WHERE j.type='integer';","3"),
   ("求全部 items 子树中 qty 叶子的总和。","通过 key='qty' 识别属性。","SELECT sum(j.atom) FROM document d,json_tree(d.body,'$.items') j WHERE j.key='qty';","6")),
 T(163,"json-set-create","JSON_SET 同时覆盖和创建属性",["JSON_SET","不可变表达式","配置更新"],
   "JSON_SET 会覆盖已有路径，也会创建缺少的对象属性。本查询把 active 设为 JSON false 并新增 reviewed=1，再抽取验证，三行都得到 0 和 1。SELECT 只是计算新文档，不修改原始存储。",
   "SELECT id,json_extract(json_set(body,'$.active',json('false'),'$.reviewed',1),'$.active'),json_extract(json_set(body,'$.reviewed',1),'$.reviewed') FROM document ORDER BY id;","1|0|1\n2|0|1\n3|0|1",
   ["直接传字符串 false 会写入 JSON 字符串。","函数返回新文本，持久化需要明确 UPDATE。"],
   ("确认原始 active 的真值数量没有改变。","计算原文档中的 true 数。","SELECT count(*) FROM document WHERE json_type(body,'$.active')='true';","2"),
   ("把 Bob 的 note 补为 pending 后读出值。","JSON_SET 会创建缺失属性。","SELECT json_extract(json_set(body,'$.note','pending'),'$.note') FROM document WHERE id=2;","pending")),
 T(164,"json-insert-replace","JSON_INSERT 与 JSON_REPLACE 的存在性语义",["JSON_INSERT","JSON_REPLACE","属性存在"],
   "对已有 note，INSERT 保持原值而 REPLACE 覆盖；对缺失 note，INSERT 创建而 REPLACE 不创建。Ann 的 JSON null 仍算属性存在，因此 INSERT 后仍是 null，Bob 则新增 new。用 JSON_TYPE 观察存在性更清楚。",
   "SELECT id,coalesce(json_type(json_insert(body,'$.note','new'),'$.note'),'missing'),coalesce(json_type(json_replace(body,'$.note','new'),'$.note'),'missing') FROM document ORDER BY id;","1|null|text\n2|text|missing\n3|text|text",
   ["JSON null 不是不存在的属性。","三个更新函数对于缺失路径的行为不同。"],
   ("对 Cara 的已有 note 使用 INSERT，读出保留值。","INSERT 不覆盖已有属性。","SELECT json_extract(json_insert(body,'$.note','new'),'$.note') FROM document WHERE id=3;","x"),
   ("对 Cara 的已有 note 使用 REPLACE。","REPLACE 会覆盖。","SELECT json_extract(json_replace(body,'$.note','new'),'$.note') FROM document WHERE id=3;","new")),
 T(165,"json-remove-array-shift","删除数组元素会移动后续下标",["JSON_REMOVE","数组下标","顺序修改"],
   "从 Ann 的 tags 删除下标 0，原来的 blue 移动到下标 0，数组变为 [blue]。数组下标是位置而非永久 id，连续删除多个位置时更要考虑前次修改的影响。Bob 的空数组删除不存在下标仍保持空。",
   "SELECT id,json_extract(json_remove(body,'$.tags[0]'),'$.tags') FROM document ORDER BY id;","1|[\"blue\"]\n2|[]\n3|[]",
   ["删除低下标后，高下标位置会改变。","对象删除属性与数组删除位置含义不同。"],
   ("删除 Ann 的 note 后检查属性是否存在。","JSON_TYPE 缺失路径为 SQL NULL。","SELECT json_type(json_remove(body,'$.note'),'$.note') IS NULL FROM document WHERE id=1;","1"),
   ("只取 Ann 原始标签的最后一个元素。","路径 [#-1] 表示最后一项。","SELECT json_extract(body,'$.tags[#-1]') FROM document WHERE id=1;","blue")),
 T(166,"json-append-array","用井号路径向 JSON 数组尾部追加",["$[#]","JSON_INSERT","数组追加"],
   "[#] 表示当前数组长度，对 tags[#] 插入 green 相当于追加。Ann 变为三元素，Bob 从空数组变为一元素，Cara 变为二元素。不要把路径写成字符串字面量下标，否则不能表达尾部位置。",
   "SELECT id,json_extract(json_insert(body,'$.tags[#]','green'),'$.tags') FROM document ORDER BY id;","1|[\"red\",\"blue\",\"green\"]\n2|[\"green\"]\n3|[\"red\",\"green\"]",
   ["追加不会自动去重已有标签。","缺失或非数组的路径需要单独规范化。"],
   ("追加后计算所有标签元素总数。","每个文档多一个标签。","SELECT sum(json_array_length(json_insert(body,'$.tags[#]','green'),'$.tags')) FROM document;","6"),
   ("给 Bob 追加 JSON 对象而非对象文本。","用 JSON 包装结构化值。","SELECT json_extract(json_insert(body,'$.items[#]',json('{\"sku\":\"C\",\"qty\":1}')),'$.items[#-1].sku') FROM document WHERE id=2;","C")),
 T(167,"json-merge-patch","MergePatch 删除属性并整体替换数组",["JSON_PATCH","RFC 7396","配置合并"],
   "JSON_PATCH 按 MergePatch 规则合并对象，补丁的 null 表示删除属性，数组则整体替换。对 Ann 应用 note:null 和 tags:[solo] 后，note 消失，tags 只剩 solo。它不执行逐元素数组合并。",
   "SELECT json_type(json_patch(body,'{\"note\":null,\"tags\":[\"solo\"]}'),'$.note') IS NULL,json_extract(json_patch(body,'{\"note\":null,\"tags\":[\"solo\"]}'),'$.tags') FROM document WHERE id=1;","1|[\"solo\"]",
   ["补丁中的 null 表示删除，不能直接用于保留 JSON null。","数组是整体替换，不是按下标深合并。"],
   ("给 Bob 合并 note 属性并取出。","补丁包含文本值。","SELECT json_extract(json_patch(body,'{\"note\":\"review\"}'),'$.note') FROM document WHERE id=2;","review"),
   ("用空对象补丁验证原始 name 不变。","空对象不会删除已有属性。","SELECT json_extract(json_patch(body,'{}'),'$.name') FROM document WHERE id=3;","Cara")),
 T(168,"json-arrow-return-types","箭头操作符区分 JSON 与 SQL 返回值",["->","->>","返回类型"],
   "-> 返回 JSON 表示，字符串仍带 JSON 引号；->> 返回 SQL 标量，姓名为普通文本。Ann 因此显示为带引号的 JSON 文本与不带引号的姓名。后续连接关系表时通常需要 ->> 的标量。",
   "SELECT id,body->'$.name',body->>'$.name' FROM document ORDER BY id;","1|\"Ann\"|Ann\n2|\"Bob\"|Bob\n3|\"Cara\"|Cara",
   ["将 -> 的字符串结果与 SQL 姓名直接比较会多一层引号。","提取数组和对象时仍需要考虑 JSON 文本结构。"],
   ("求 active 的 SQL 返回类型。","TYPEOF 作用于 ->> 结果。","SELECT id,typeof(body->>'$.active') FROM document ORDER BY id;","1|integer\n2|integer\n3|integer"),
   ("用 ->> 查找姓名为 Ann 的文档。","与普通 SQL 文本比较。","SELECT id FROM document WHERE body->>'$.name'='Ann' ORDER BY id;","1")),
 T(169,"json-build-array-report","有序聚合生成可重复 JSON 报表",["JSON_GROUP_ARRAY","聚合 ORDER BY","结构输出"],
   "聚合内部 ORDER BY 决定 JSON 数组的元素顺序，而外层 ORDER BY 只排序结果行。按 id 收集姓名得到 Ann、Bob、Cara。用 JSON_OBJECT 构建结构时，标量值会被正确编码，避免手工拼接引号和转义。",
   "SELECT json_group_array(json_extract(body,'$.name') ORDER BY id) FROM document;","[\"Ann\",\"Bob\",\"Cara\"]",
   ["不指定聚合内部排序，数组顺序不能作为稳定契约。","不要通过字符串拼接构造 JSON。"],
   ("按 id 逆序构造姓名数组。","聚合内部使用 DESC。","SELECT json_group_array(body->>'$.name' ORDER BY id DESC) FROM document;","[\"Cara\",\"Bob\",\"Ann\"]"),
   ("构建包含文档数和真值数的 JSON 对象。","JSON_OBJECT 接收键值对。","SELECT json_object('documents',count(*),'active',sum(json_type(body,'$.active')='true')) FROM document;","{\"documents\":3,\"active\":2}")),
 T(170,"json-cartesian-trap","多数组独立汇总避免笛卡尔放大",["多数组","相关子查询","粒度保护"],
   "同一文档的 tags 与 items 若同时展开，会相互相乘。分别用相关子查询统计两个数组，Ann 的标签数 2、商品件数 3 保持正确；把四个展开组合直接求和会把件数翻倍。",
   "SELECT d.id,(SELECT count(*) FROM json_each(d.body,'$.tags')),coalesce((SELECT sum(value->>'$.qty') FROM json_each(d.body,'$.items')),0) FROM document d ORDER BY id;","1|2|3\n2|0|3\n3|1|0",
   ["两个一对多展开会产生乘法行数。","先明确报表是一文档一行还是一商品一行。"],
   ("计算 Ann 两个数组一起展开的组合行数。","2 个标签乘 2 个行项目。","SELECT count(*) FROM document d,json_each(d.body,'$.tags') t,json_each(d.body,'$.items') i WHERE d.id=1;","4"),
   ("不放大数组地查找同时有 red 标签和 A 商品的文档。","两个独立 EXISTS。","SELECT d.id FROM document d WHERE EXISTS(SELECT 1 FROM json_each(d.body,'$.tags') WHERE value='red') AND EXISTS(SELECT 1 FROM json_each(d.body,'$.items') WHERE value->>'$.sku'='A') ORDER BY d.id;","1")),
 T(171,"json-shape-validation","有效 JSON 仍需要业务形状校验",["JSON_VALID","JSON_TYPE","结构契约"],
   "JSON_VALID 只检查 JSON 语法，不保证字段名称和类型。样本数组 tags 合法但 qty 为文本，因此严格数量类型校验失败。对配置导入应分开报告语法、结构和业务值错误，而不是把能解析视为可使用。",
   "WITH incoming(id,body) AS(VALUES(1,'{\"tags\":[],\"qty\":2}'),(2,'{\"tags\":[],\"qty\":\"2\"}'),(3,'{\"tags\":\"red\",\"qty\":2}')) SELECT id,json_type(body,'$.tags')='array' AND json_type(body,'$.qty')='integer' FROM incoming ORDER BY id;","1|1\n2|0\n3|0",
   ["有效 JSON 可以是标量，未必是业务对象。","检查可能无效的外部文本前，先保护 JSON 函数调用。"],
   ("对非法文本只返回语法合法性。","JSON_VALID 不会因非法 JSON 抛解析错误。","SELECT json_valid('{bad}'),json_valid('{\"qty\":2}');","0|1"),
   ("找出当前文档的所有非空 note 文本。","严格要求 JSON 类型 text。","SELECT id,body->>'$.note' FROM document WHERE json_type(body,'$.note')='text' ORDER BY id;","3|x")),
]
